{
  "name": "AI Agent Architect",
  "description": "An application for creating AI-powered agents, project guidelines, and constraints. Users define an agent's role and scope, and the AI transforms these inputs into a comprehensive set of structured project files, streamlining the development of AI-driven applications."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useCallback } from 'react';
import { AgentConfig, GeneratedFiles } from './types';
import { generateAgentFiles } from './services/geminiService';
import Header from './components/Header';
import AgentForm from './components/AgentForm';
import GeneratedFilesDisplay from './components/GeneratedFilesDisplay';
import LoadingSpinner from './components/LoadingSpinner';

const App: React.FC = () => {
  const [agentConfig, setAgentConfig] = useState<AgentConfig>({
    role: '',
    scope: '',
    goals: '',
    constraints: '',
  });
  const [generatedFiles, setGeneratedFiles] = useState<GeneratedFiles | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setGeneratedFiles(null);
    try {
      if (!agentConfig.role || !agentConfig.scope) {
        setError("Agent Role and Scope are required fields.");
        setIsLoading(false);
        return;
      }
      const files = await generateAgentFiles(agentConfig);
      setGeneratedFiles(files);
    } catch (e) {
      setError('Failed to generate agent files. Please check your API key and try again.');
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  }, [agentConfig]);

  const handleReset = () => {
    setAgentConfig({
      role: '',
      scope: '',
      goals: '',
      constraints: '',
    });
    setGeneratedFiles(null);
    setError(null);
    setIsLoading(false);
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 transition-colors duration-300">
      <Header />
      <main className="container mx-auto p-4 md:p-8">
        <div className="max-w-4xl mx-auto">
          <p className="text-center text-lg text-gray-600 dark:text-gray-400 mb-8">
            Define your AI agent's characteristics, and we'll generate the foundational documents for your project.
          </p>

          <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-6 md:p-8">
            <AgentForm 
              agentConfig={agentConfig} 
              setAgentConfig={setAgentConfig} 
              onGenerate={handleGenerate}
              onReset={handleReset}
              isLoading={isLoading} 
            />
          </div>

          {error && (
            <div className="mt-8 bg-red-100 dark:bg-red-900 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-200 px-4 py-3 rounded-lg relative" role="alert">
              <strong className="font-bold">Error: </strong>
              <span className="block sm:inline">{error}</span>
            </div>
          )}

          {isLoading && <LoadingSpinner />}

          {generatedFiles && !isLoading && (
            <div className="mt-8">
              <GeneratedFilesDisplay files={generatedFiles} />
            </div>
          )}
        </div>
      </main>
      <footer className="text-center p-4 text-sm text-gray-500 dark:text-gray-400">
        <p>Powered by Gemini. Built with React & Tailwind CSS.</p>
      </footer>
    </div>
  );
};

export default App;

export interface AgentConfig {
  role: string;
  scope: string;
  goals: string;
  constraints: string;
}

export interface GeneratedFiles {
  agentFile: string;
  projectGuidelines: string;
  constraintsFile: string;
}

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { AgentConfig, GeneratedFiles } from '../types';

if (!process.env.API_KEY) {
  throw new Error("API_KEY environment variable is not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const generatePrompt = (config: AgentConfig): string => {
  return `
    Based on the following agent configuration, generate a comprehensive set of project files in JSON format.
    The JSON object should have three keys: "agentFile", "projectGuidelines", and "constraintsFile".
    Each key should contain a string with the content of the respective file in Markdown format.

    **Agent Configuration:**
    - **Role:** ${config.role}
    - **Scope:** ${config.scope}
    - **Goals:** ${config.goals || 'Not specified'}
    - **Constraints:** ${config.constraints || 'Not specified'}

    **File Generation Instructions:**

    1.  **agentFile (Markdown):**
        - Create a detailed agent persona.
        - Define its primary functions and responsibilities based on the role and scope.
        - List its core capabilities and skills.
        - Specify the communication style and tone.

    2.  **projectGuidelines (Markdown):**
        - Formulate a clear project mission statement.
        - Outline the key objectives and success metrics based on the agent's goals.
        - Describe the target audience and user interaction model.
        - Provide high-level technical and design principles.

    3.  **constraintsFile (Markdown):**
        - Detail the operational boundaries and limitations (the 'guardrails').
        - List any ethical considerations or restricted topics.
        - Specify any technical constraints or dependencies.
        - Include any user-provided constraints.

    Return only the raw JSON object, with no surrounding text or code blocks.
  `;
};

export const generateAgentFiles = async (config: AgentConfig): Promise<GeneratedFiles> => {
  const prompt = generatePrompt(config);

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            agentFile: { type: Type.STRING },
            projectGuidelines: { type: Type.STRING },
            constraintsFile: { type: Type.STRING },
          },
          required: ['agentFile', 'projectGuidelines', 'constraintsFile'],
        },
        temperature: 0.7,
      },
    });

    if (response.text) {
        const jsonString = response.text;
        const parsedResult: GeneratedFiles = JSON.parse(jsonString);
        return parsedResult;
    } else {
        throw new Error("Received an empty response from the API.");
    }
  } catch (error) {
    console.error("Error generating agent files with Gemini:", error);
    throw new Error("Failed to communicate with the Gemini API.");
  }
};

import React from 'react';

const Header: React.FC = () => {
  return (
    <header className="bg-white dark:bg-gray-800 shadow-md">
      <div className="container mx-auto px-4 py-4 flex items-center justify-center">
        <span className="material-icons text-3xl md:text-4xl text-blue-500 dark:text-blue-400 mr-3">
          smart_toy
        </span>
        <h1 className="text-2xl md:text-3xl font-bold text-gray-800 dark:text-gray-100">
          AI Agent Architect
        </h1>
      </div>
    </header>
  );
};

export default Header;

import React from 'react';
import { AgentConfig } from '../types';

interface AgentFormProps {
  agentConfig: AgentConfig;
  setAgentConfig: React.Dispatch<React.SetStateAction<AgentConfig>>;
  onGenerate: () => void;
  onReset: () => void;
  isLoading: boolean;
}

const AgentForm: React.FC<AgentFormProps> = ({ agentConfig, setAgentConfig, onGenerate, onReset, isLoading }) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setAgentConfig(prev => ({ ...prev, [name]: value }));
  };

  const isGenerateDisabled = !agentConfig.role || !agentConfig.scope || isLoading;

  return (
    <form onSubmit={(e) => { e.preventDefault(); onGenerate(); }} className="space-y-6">
      <h2 className="text-2xl font-semibold text-center text-gray-800 dark:text-gray-200 mb-6">Define Your Agent</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label htmlFor="role" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Agent Role <span className="text-red-500">*</span></label>
          <input
            type="text"
            id="role"
            name="role"
            value={agentConfig.role}
            onChange={handleChange}
            placeholder="e.g., Expert Financial Advisor"
            required
            className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition"
          />
        </div>
        <div>
          <label htmlFor="scope" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Project Scope <span className="text-red-500">*</span></label>
          <input
            type="text"
            id="scope"
            name="scope"
            value={agentConfig.scope}
            onChange={handleChange}
            placeholder="e.g., Personal investment tracking app"
            required
            className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition"
          />
        </div>
      </div>

      <div>
        <label htmlFor="goals" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Primary Goals (Optional)</label>
        <textarea
          id="goals"
          name="goals"
          rows={3}
          value={agentConfig.goals}
          onChange={handleChange}
          placeholder="e.g., Help users maximize returns, educate on market trends, simplify portfolio management."
          className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition"
        />
      </div>

      <div>
        <label htmlFor="constraints" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Constraints & Guardrails (Optional)</label>
        <textarea
          id="constraints"
          name="constraints"
          rows={3}
          value={agentConfig.constraints}
          onChange={handleChange}
          placeholder="e.g., Do not give direct buy/sell advice, avoid speculative assets, always disclose risks."
          className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition"
        />
      </div>

      <div className="flex flex-col sm:flex-row items-center justify-end space-y-4 sm:space-y-0 sm:space-x-4 pt-4">
        <button
          type="button"
          onClick={onReset}
          disabled={isLoading}
          className="w-full sm:w-auto px-6 py-2 border border-gray-300 dark:border-gray-500 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500 disabled:opacity-50 transition"
        >
          Reset
        </button>
        <button
          type="submit"
          disabled={isGenerateDisabled}
          className="w-full sm:w-auto flex items-center justify-center px-6 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-300 dark:disabled:bg-blue-800 disabled:cursor-not-allowed transition"
        >
          {isLoading && <span className="material-icons animate-spin mr-2">sync</span>}
          {isLoading ? 'Generating...' : 'Generate Files'}
        </button>
      </div>
    </form>
  );
};

export default AgentForm;

import React, { useState } from 'react';
import { GeneratedFiles } from '../types';

interface GeneratedFilesDisplayProps {
  files: GeneratedFiles;
}

type Tab = 'agentFile' | 'projectGuidelines' | 'constraintsFile';

const FileContent: React.FC<{ content: string }> = ({ content }) => (
    <div className="prose prose-sm sm:prose-base dark:prose-invert max-w-none p-4 md:p-6 bg-gray-100 dark:bg-gray-900 rounded-b-lg whitespace-pre-wrap font-mono">
        <pre><code className="text-sm">{content}</code></pre>
    </div>
);


const GeneratedFilesDisplay: React.FC<GeneratedFilesDisplayProps> = ({ files }) => {
  const [activeTab, setActiveTab] = useState<Tab>('agentFile');

  const tabs: { id: Tab; label: string; icon: string }[] = [
    { id: 'agentFile', label: 'Agent File', icon: 'person' },
    { id: 'projectGuidelines', label: 'Guidelines', icon: 'rule' },
    { id: 'constraintsFile', label: 'Constraints', icon: 'gavel' },
  ];

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text).then(() => {
        // You can add a toast notification here for better UX
        console.log('Copied to clipboard');
    });
  };

  return (
    <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg mt-10">
        <div className="flex justify-between items-center p-4 border-b border-gray-200 dark:border-gray-700">
            <h3 className="text-xl font-semibold">Generated Project Files</h3>
            <button
                onClick={() => copyToClipboard(files[activeTab])}
                className="flex items-center px-3 py-1.5 border border-gray-300 dark:border-gray-600 rounded-md text-sm font-medium text-gray-700 dark:text-gray-300 bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 transition"
                title={`Copy ${tabs.find(t => t.id === activeTab)?.label}`}
            >
                <span className="material-icons text-base mr-1.5">content_copy</span>
                Copy
            </button>
        </div>
      <div className="border-b border-gray-200 dark:border-gray-700">
        <nav className="-mb-px flex space-x-1 sm:space-x-4 px-4" aria-label="Tabs">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`
                ${activeTab === tab.id
                  ? 'border-blue-500 text-blue-600 dark:border-blue-400 dark:text-blue-300'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300 dark:text-gray-400 dark:hover:text-gray-200 dark:hover:border-gray-600'
                }
                flex items-center whitespace-nowrap py-4 px-1 sm:px-2 border-b-2 font-medium text-sm transition-colors focus:outline-none
              `}
            >
              <span className="material-icons text-base mr-2">{tab.icon}</span>
              {tab.label}
            </button>
          ))}
        </nav>
      </div>
      <div>
        <FileContent content={files[activeTab]} />
      </div>
    </div>
  );
};

export default GeneratedFilesDisplay;

import React from 'react';

const LoadingSpinner: React.FC = () => {
  return (
    <div className="flex flex-col items-center justify-center my-12 text-center">
      <div className="relative w-16 h-16">
        <div className="absolute top-0 left-0 w-full h-full border-4 border-gray-200 dark:border-gray-700 rounded-full"></div>
