import React, { useState, useCallback } from 'react';
import { AgentConfig, GeneratedFiles } from '../types';
import { generateAgentFiles } from '../services/geminiService';
import AgentForm from './AgentForm';
import GeneratedFilesDisplay from './GeneratedFilesDisplay';
import LoadingSpinner from './LoadingSpinner';

const AgentArchitect: React.FC = () => {
  const [agentConfig, setAgentConfig] = useState<AgentConfig>({
    role: '',
    scope: '',
    goals: '',
    constraints: '',
  });
  const [generatedFiles, setGeneratedFiles] = useState<GeneratedFiles | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setGeneratedFiles(null);
    try {
      if (!agentConfig.role || !agentConfig.scope) {
        setError("Agent Role and Scope are required fields.");
        setIsLoading(false);
        return;
      }
      const files = await generateAgentFiles(agentConfig);
      setGeneratedFiles(files);
    } catch (e) {
      setError('Failed to generate agent files. Please check your API key and try again.');
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  }, [agentConfig]);

  const handleReset = () => {
    setAgentConfig({
      role: '',
      scope: '',
      goals: '',
      constraints: '',
    });
    setGeneratedFiles(null);
    setError(null);
    setIsLoading(false);
  };

  return (
    <div className="max-w-4xl mx-auto">
      <p className="text-center text-lg text-gray-600 dark:text-gray-400 mb-8">
        Define your AI agent's characteristics, and we'll generate the foundational documents for your project.
      </p>

      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-6 md:p-8">
        <AgentForm 
          agentConfig={agentConfig} 
          setAgentConfig={setAgentConfig} 
          onGenerate={handleGenerate}
          onReset={handleReset}
          isLoading={isLoading} 
        />
      </div>

      {error && (
        <div className="mt-8 bg-red-100 dark:bg-red-900 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-200 px-4 py-3 rounded-lg relative" role="alert">
          <strong className="font-bold">Error: </strong>
          <span className="block sm:inline">{error}</span>
        </div>
      )}

      {isLoading && <LoadingSpinner />}

      {generatedFiles && !isLoading && (
        <div className="mt-8">
          <GeneratedFilesDisplay files={generatedFiles} />
        </div>
      )}
    </div>
  );
};

export default AgentArchitect;

import React from 'react';
import { View } from '../App';

interface LandingPageProps {
