import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { AgentConfig, GeneratedFiles } from '../types';

if (!process.env.API_KEY) {
  throw new Error("API_KEY environment variable is not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const generatePrompt = (config: AgentConfig): string => {
  return `
    Based on the following agent configuration, generate a comprehensive set of project files in JSON format.
    The JSON object should have three keys: "agentFile", "projectGuidelines", and "constraintsFile".
    Each key should contain a string with the content of the respective file in Markdown format.

    **Agent Configuration:**
    - **Role:** ${config.role}
    - **Scope:** ${config.scope}
    - **Goals:** ${config.goals || 'Not specified'}
    - **Constraints:** ${config.constraints || 'Not specified'}

    **File Generation Instructions:**

    1.  **agentFile (Markdown):**
        - Create a detailed agent persona.
        - Define its primary functions and responsibilities based on the role and scope.
        - List its core capabilities and skills.
        - Specify the communication style and tone.

    2.  **projectGuidelines (Markdown):**
        - Formulate a clear project mission statement.
        - Outline the key objectives and success metrics based on the agent's goals.
        - Describe the target audience and user interaction model.
        - Provide high-level technical and design principles.

    3.  **constraintsFile (Markdown):**
        - Detail the operational boundaries and limitations (the 'guardrails').
        - List any ethical considerations or restricted topics.
        - Specify any technical constraints or dependencies.
        - Include any user-provided constraints.

    Return only the raw JSON object, with no surrounding text or code blocks.
  `;
};

export const generateAgentFiles = async (config: AgentConfig): Promise<GeneratedFiles> => {
  const prompt = generatePrompt(config);

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            agentFile: { type: Type.STRING },
            projectGuidelines: { type: Type.STRING },
            constraintsFile: { type: Type.STRING },
          },
          required: ['agentFile', 'projectGuidelines', 'constraintsFile'],
        },
        temperature: 0.7,
      },
    });

    if (response.text) {
        const jsonString = response.text;
        const parsedResult: GeneratedFiles = JSON.parse(jsonString);
        return parsedResult;
    } else {
        throw new Error("Received an empty response from the API.");
    }
  } catch (error) {
    console.error("Error generating agent files with Gemini:", error);
    throw new Error("Failed to communicate with the Gemini API.");
  }
};

const createMetaPromptForFrictionProtocol = (goal: string) => `
You are an expert in prompt engineering. Your task is to create a new, structured system prompt based on the user's desired goal.

The new prompt you generate MUST be a ready-to-use system prompt that perfectly embodies the structure and principles of the "GENERATIVE FRICTION PROTOCOL". The purpose of the generated prompt is to guide an AI to act as an intellectual partner for the user's stated goal.

**User's Goal for the Prompt:**
"${goal}"

---

**THE TEMPLATE TO USE (GENERATIVE FRICTION PROTOCOL - INTELLECTUAL PARTNERSHIP):**

PURPOSE
Transform the assistant from a compliant "pleaser" into a rigorous intellectual partner. Encourages productive disagreement that forces ideas to develop through dialogue rather than being presented fully-formed.

CORE INSTRUCTIONS
When a user presents a claim, theory, or framework related to **${goal}**, the system must:

1. Steelman the Position
Identify and articulate the strongest, most coherent version of the user's position before challenging it. Ensure the user feels their core intent is fully understood.

2. Identify the Productive Tension Point
Locate the specific area where the framework is most vulnerable, where evidence is thinnest, or where a systemic constraint has been overlooked.

3. Offer Collaborative Friction
Present challenges not as contradictions or rejections, but as "friction" required for the idea to gain traction and develop.

4. Distinguish Blind Spots from Errors
Frame observations as "interesting blind spots" or "unexplored constraints" rather than simple errors. The goal is to expand the idea's boundary, not to invalidate it.

OPERATIONAL GUIDELINES
- Avoid reflexive agreement ("I totally agree," "You're right").
- Use phrases like: "To gain traction on this idea, we need to push on [Area X]..." or "The strongest version of this is Y, but that creates a tension with Z..."
- Maintain a tone of high-context collaboration.

The goal is not to reach agreement, but to reach a higher level of synthesis through shared resistance.

---

Now, generate the complete, ready-to-use system prompt tailored for the user's goal.
The output should be ONLY the generated prompt text itself, starting with "GENERATIVE FRICTION PROTOCOL...". Do not include any extra explanations, introductions, or surrounding text.
`;

export const generateFrictionProtocolPrompt = async (userInput: string): Promise<string> => {
  if (!userInput.trim()) {
    throw new Error("User input cannot be empty.");
  }

  const metaPrompt = createMetaPromptForFrictionProtocol(userInput);

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: metaPrompt,
      config: {
        temperature: 0.5,
      },
    });

    if (response.text) {
      return response.text;
    } else {
      throw new Error("Received an empty response from the API.");
    }
  } catch (error) {
    console.error("Error generating friction protocol prompt:", error);
    throw new Error("Failed to communicate with the Gemini API.");
  }
};

