    const [promptConfig, setPromptConfig] = useState<PromptConfig>({ goal: '', instructions: '' });
    const [generatedPrompt, setGeneratedPrompt] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setPromptConfig(prev => ({...prev, [name]: value}));
    }

    const handleGenerate = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        setGeneratedPrompt('');
        try {
            if (!promptConfig.goal.trim()) {
                setError("Please enter a goal for your prompt.");
                setIsLoading(false);
                return;
            }
            const result = await generateStructuredPrompt(promptConfig);
            setGeneratedPrompt(result);
        } catch (e) {
            setError('Failed to generate prompt. Please check your API key and try again.');
            console.error(e);
        } finally {
            setIsLoading(false);
        }
    }, [promptConfig]);

    const handleReset = () => {
        setPromptConfig({ goal: '', instructions: '' });
        setGeneratedPrompt('');
        setError(null);
        setIsLoading(false);
    };

    const isGenerateDisabled = !promptConfig.goal.trim() || isLoading;

    return (
        <div className="max-w-4xl mx-auto">
            <div className="text-center">
                <h2 className="text-3xl font-bold text-gray-900 dark:text-gray-100">Prompt Architect</h2>
                <p className="mt-2 text-lg text-gray-600 dark:text-gray-400">
                    Transform your raw ideas into a powerful, structured prompt for any AI.
                </p>
            </div>

            <div className="mt-8 bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-6 md:p-8">
                <form onSubmit={(e) => { e.preventDefault(); handleGenerate(); }} className="space-y-6">
                    <div>
                        <label htmlFor="goal" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                            Prompt Goal / Core Task <span className="text-red-500">*</span>
                        </label>
                        <input
                            type="text"
                            id="goal"
                            name="goal"
                            value={promptConfig.goal}
                            onChange={handleChange}
                            placeholder="e.g., 'Summarize technical articles for a beginner audience'"
                            required
                            className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition"
                        />
                    </div>
                    <div>
                        <label htmlFor="instructions" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                            Key Instructions, Constraints, or Steps (Optional)
                        </label>
                        <textarea
                            id="instructions"
                            name="instructions"
                            rows={5}
                            value={promptConfig.instructions}
                            onChange={handleChange}
                            placeholder="e.g., 'The summary must be in 3 bullet points. Avoid jargon. Mention the key takeaways for a marketer.'"
                            className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition"
                        />
                    </div>
                    <div className="flex flex-col sm:flex-row items-center justify-end space-y-4 sm:space-y-0 sm:space-x-4 pt-2">
                        <button
                            type="button"
                            onClick={handleReset}
                            disabled={isLoading}
                            className="w-full sm:w-auto px-6 py-2 border border-gray-300 dark:border-gray-500 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500 disabled:opacity-50 transition"
                        >
                            Reset
                        </button>
                        <button
                            type="submit"
                            disabled={isGenerateDisabled}
                            className="w-full sm:w-auto flex items-center justify-center px-6 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-300 dark:disabled:bg-blue-800 disabled:cursor-not-allowed transition"
                        >
                            {isLoading && <span className="material-icons animate-spin mr-2">sync</span>}
                            {isLoading ? 'Architecting...' : 'Generate Prompt'}
                        </button>
                    </div>
                </form>
            </div>

            {error && (
                <div className="mt-8 bg-red-100 dark:bg-red-900 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-200 px-4 py-3 rounded-lg relative" role="alert">
                    <strong className="font-bold">Error: </strong>
                    <span className="block sm:inline">{error}</span>
                </div>
            )}

            {isLoading && <LoadingSpinner />}

            {generatedPrompt && !isLoading && (
                <div className="mt-8 bg-white dark:bg-gray-800 rounded-2xl shadow-lg">
                     <div className="flex justify-between items-center p-4 border-b border-gray-200 dark:border-gray-700">
                        <h3 className="text-xl font-semibold">Your Generated Prompt</h3>
                        <button
                            onClick={() => navigator.clipboard.writeText(generatedPrompt)}
                            className="flex items-center px-3 py-1.5 border border-gray-300 dark:border-gray-600 rounded-md text-sm font-medium text-gray-700 dark:text-gray-300 bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 transition"
                            title="Copy prompt"
                        >
                            <span className="material-icons text-base mr-1.5">content_copy</span>
                            Copy
                        </button>
                    </div>
                    <div className="prose prose-sm sm:prose-base dark:prose-invert max-w-none p-4 md:p-6 bg-gray-100 dark:bg-gray-900 rounded-b-lg whitespace-pre-wrap font-mono">
                        <pre><code className="text-sm">{generatedPrompt}</code></pre>
                    </div>
                </div>
            )}
        </div>
    );
};

export default PromptArchitect;

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { AgentConfig, GeneratedFiles, PromptConfig } from '../types';

if (!process.env.API_KEY) {
  throw new Error("API_KEY environment variable is not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const createAgentFilesMetaPrompt = (config: AgentConfig): string => {
  return `
You are an expert AI Systems Architect. Your task is to take a user's high-level agent configuration and generate a set of comprehensive, structured project files.

The final output MUST be a single, raw JSON object with no surrounding text or markdown code blocks. The JSON object must have three keys: "agentFile", "projectGuidelines", and "constraintsFile". Each key's value must be a string containing the full content of the respective file in Markdown format.

**User's Agent Configuration:**
- **Role:** ${config.role}
- **Scope:** ${config.scope}
- **Primary Goals:** ${config.goals || 'Not specified'}
- **Constraints & Guardrails:** ${config.constraints || 'Not specified'}

---

**Detailed File Generation Instructions:**

1.  **agentFile (Markdown String):**
    - Create a detailed agent persona based on the provided Role.
    - Define its primary functions and responsibilities based on the Scope.
    - List its core capabilities and skills.
    - Specify a suitable communication style and tone.

2.  **projectGuidelines (Markdown String):**
    - Formulate a clear project mission statement from the Scope and Goals.
    - Outline key objectives and success metrics based on the agent's Goals.
    - Describe the target audience and user interaction model.
    - Provide high-level technical and design principles relevant to the project.

3.  **constraintsFile (Markdown String):**
    - Detail the operational boundaries and limitations (the 'guardrails').
    - List any ethical considerations or restricted topics implied by the configuration.
    - Specify any technical constraints or dependencies that might be relevant.
    - Directly include any user-provided constraints.

Generate ONLY the raw JSON object as described.
  `;
};

export const generateAgentFiles = async (config: AgentConfig): Promise<GeneratedFiles> => {
  const prompt = createAgentFilesMetaPrompt(config);

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            agentFile: { type: Type.STRING },
            projectGuidelines: { type: Type.STRING },
            constraintsFile: { type: Type.STRING },
          },
          required: ['agentFile', 'projectGuidelines', 'constraintsFile'],
        },
        temperature: 0.7,
      },
    });

    if (response.text) {
        const jsonString = response.text;
        const parsedResult: GeneratedFiles = JSON.parse(jsonString);
        return parsedResult;
    } else {
        throw new Error("Received an empty response from the API.");
    }
  } catch (error) {
    console.error("Error generating agent files with Gemini:", error);
    throw new Error("Failed to communicate with the Gemini API.");
  }
};

const createStructuredPromptMetaPrompt = (config: PromptConfig) => `
You are an expert Prompt Engineering Assistant. Your task is to take a user's raw goal and key instructions and transform them into a well-structured, clear, and highly effective system prompt.

The final prompt you generate should be detailed, unambiguous, and ready for another AI to use. Structure the output using clear headings in Markdown format (e.g., ### ROLE, ### TASK).

User's raw input:
- **Core Task/Goal:** ${config.goal}
- **Key Instructions/Constraints:** ${config.instructions || 'None provided.'}

Based on the user's input, create a comprehensive system prompt. If the user provides specific instructions, incorporate them directly into the relevant sections. If parts are unspecified, use your expertise to add logical details or create sections that would make the prompt more robust (like suggesting an output format if not given).

A good structure often includes:
- **### ROLE AND GOAL:** Define the AI's persona and its primary objective.
- **### CONTEXT:** Provide any necessary background information.
- **### STEP-BY-STEP INSTRUCTIONS:** A clear sequence of actions for the AI to follow.
- **### CONSTRAINTS:** Rules, limitations, and things to avoid.
- **### OUTPUT FORMAT:** Specify how the final output should be formatted (e.g., JSON, Markdown, a list).

Generate ONLY the final, structured prompt. Do not include any conversational text or explanations about what you did.
`;


export const generateStructuredPrompt = async (config: PromptConfig): Promise<string> => {
  if (!config.goal.trim()) {
    throw new Error("Prompt goal cannot be empty.");
  }

  const metaPrompt = createStructuredPromptMetaPrompt(config);

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: metaPrompt,
      config: {
        temperature: 0.6,
      },
    });

    if (response.text) {
      return response.text;
    } else {
      throw new Error("Received an empty response from the API.");
    }
  } catch (error) {
    console.error("Error generating structured prompt:", error);
    throw new Error("Failed to communicate with the Gemini API.");
  }
};

import { SavedAgent, SavedPrompt } from '../types';

const DB_NAME = 'NoosphereArchitectDB';
const DB_VERSION = 1;
const AGENT_STORE = 'savedAgents';
const PROMPT_STORE = 'savedPrompts';

let dbInstance: IDBDatabase | null = null;

const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    if (dbInstance) {
      resolve(dbInstance);
      return;
    }

    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => {
      console.error('Error opening DB', request.error);
      reject('Error opening DB');
    };

    request.onsuccess = () => {
      dbInstance = request.result;
      resolve(dbInstance);
    };

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(AGENT_STORE)) {
        const agentStore = db.createObjectStore(AGENT_STORE, { keyPath: 'id', autoIncrement: true });
        agentStore.createIndex('name', 'name', { unique: false });
        agentStore.createIndex('createdAt', 'createdAt', { unique: false });
      }
      if (!db.objectStoreNames.contains(PROMPT_STORE)) {
        const promptStore = db.createObjectStore(PROMPT_STORE, { keyPath: 'id', autoIncrement: true });
        promptStore.createIndex('name', 'name', { unique: false });
        promptStore.createIndex('createdAt', 'createdAt', { unique: false });
      }
    };
  });
};

const getStore = async (storeName: string, mode: IDBTransactionMode) => {
  const db = await initDB();
  const tx = db.transaction(storeName, mode);
  return tx.objectStore(storeName);
};

// Agent Functions
export const addAgent = (agent: SavedAgent): Promise<number> => {
    return new Promise(async (resolve, reject) => {
        const store = await getStore(AGENT_STORE, 'readwrite');
        const request = store.add(agent);
        request.onsuccess = () => resolve(request.result as number);
        request.onerror = () => reject(request.error);
    });
};

export const getAllAgents = (): Promise<SavedAgent[]> => {
    return new Promise(async (resolve, reject) => {
        const store = await getStore(AGENT_STORE, 'readonly');
        const request = store.getAll();
        request.onsuccess = () => resolve(request.result.sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()));
        request.onerror = () => reject(request.error);
    });
};

export const updateAgent = (agent: SavedAgent): Promise<number> => {
    return new Promise(async (resolve, reject) => {
        const store = await getStore(AGENT_STORE, 'readwrite');
        const request = store.put(agent);
        request.onsuccess = () => resolve(request.result as number);
        request.onerror = () => reject(request.error);
    });
};

export const deleteAgent = (id: number): Promise<void> => {
    return new Promise(async (resolve, reject) => {
        const store = await getStore(AGENT_STORE, 'readwrite');
        const request = store.delete(id);
        request.onsuccess = () => resolve();
        request.onerror = () => reject(request.error);
    });
};

// Prompt Functions
export const addPrompt = (prompt: SavedPrompt): Promise<number> => {
    return new Promise(async (resolve, reject) => {
        const store = await getStore(PROMPT_STORE, 'readwrite');
        const request = store.add(prompt);
        request.onsuccess = () => resolve(request.result as number);
        request.onerror = () => reject(request.error);
    });
};

export const getAllPrompts = (): Promise<SavedPrompt[]> => {
    return new Promise(async (resolve, reject) => {
        const store = await getStore(PROMPT_STORE, 'readonly');
