                            <button onClick={() => handleDelete(agent.id!)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-red-500 transition-colors" title="Delete"><span className="material-icons">delete</span></button>
                        </div>
                    </div>
                ))}
