import React, { useState } from 'react';
import { AgentConfig } from '../types';

interface AgentFormProps {
  agentConfig: AgentConfig;
  setAgentConfig: React.Dispatch<React.SetStateAction<AgentConfig>>;
  onGenerate: () => void;
  onReset: () => void;
  isLoading: boolean;
}

const Tooltip: React.FC<{ text: string }> = ({ text }) => (
  <span className="absolute left-1/2 -translate-x-1/2 bottom-full mb-2 w-max max-w-xs p-2 bg-gray-800 text-white text-xs rounded-md shadow-lg opacity-0 group-hover:opacity-100 transition-opacity z-10 pointer-events-none">
    {text}
  </span>
);

const steps = [
  { id: 'role', label: 'Role', tooltip: "A concise title for your agent, like 'Expert Financial Advisor' or 'Creative Storyteller'." },
  { id: 'scope', label: 'Scope', tooltip: "The project or context where the agent operates, e.g., 'Personal investment tracking app'." },
  { id: 'goals', label: 'Goals', tooltip: "Key objectives for the agent, like 'Help users maximize returns, educate on market trends'." },
  { id: 'constraints', label: 'Constraints', tooltip: "Specific limitations or rules, e.g., 'Do not give direct buy/sell advice, avoid speculative assets'." },
];

const AgentForm: React.FC<AgentFormProps> = ({ agentConfig, setAgentConfig, onGenerate, onReset, isLoading }) => {
  const [currentStep, setCurrentStep] = useState(0);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setAgentConfig(prev => ({ ...prev, [name]: value }));
  };

  const handleReset = () => {
      setCurrentStep(0);
      onReset();
  }

  const isLastStep = currentStep === steps.length - 1;
  const isGenerateDisabled = !agentConfig.role || !agentConfig.scope || isLoading;

  const renderStepContent = () => {
    const step = steps[currentStep];
    const isRequired = step.id === 'role' || step.id === 'scope';

    return (
      <div key={step.id} className="space-y-6 animate-fade-in">
        <div>
          <label htmlFor={step.id} className="flex items-center text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            {step.label} {isRequired ? <span className="text-red-500 ml-1">*</span> : '(Optional)'}
            <div className="group relative flex items-center ml-2">
                <span className="material-icons text-gray-400 dark:text-gray-500 text-base cursor-help">info_outline</span>
                <Tooltip text={step.tooltip} />
            </div>
          </label>
          {step.id === 'goals' || step.id === 'constraints' ? (
             <textarea
                id={step.id}
                name={step.id}
                rows={5}
                value={agentConfig[step.id as keyof AgentConfig]}
                onChange={handleChange}
                placeholder={`e.g., ${step.tooltip.split(', ')[1] || step.tooltip}`}
                className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition"
              />
          ) : (
            <input
              type="text"
              id={step.id}
              name={step.id}
              value={agentConfig[step.id as keyof AgentConfig]}
              onChange={handleChange}
              placeholder={`e.g., ${step.tooltip.split(' ')[4]} ${step.tooltip.split(' ')[5]}`}
              required={isRequired}
              className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition"
            />
          )}
        </div>
      </div>
    );
  };

  return (
    <form onSubmit={(e) => { e.preventDefault(); if(isLastStep) onGenerate(); }} className="space-y-8">
        <h2 className="text-2xl font-semibold text-center text-gray-800 dark:text-gray-200">Define Your Agent</h2>

        <div>
            <div className="flex justify-between mb-1">
                {steps.map((step, index) => (
                    <span key={step.id} className={`text-xs font-medium ${currentStep >= index ? 'text-blue-600 dark:text-blue-400' : 'text-gray-400 dark:text-gray-500'}`}>
                        {step.label}
                    </span>
                ))}
            </div>
            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
                <div className="bg-blue-600 h-2 rounded-full transition-all duration-300" style={{ width: `${((currentStep + 1) / steps.length) * 100}%` }}></div>
            </div>
        </div>

        <div>{renderStepContent()}</div>

        <div className="flex flex-col sm:flex-row items-center justify-between pt-4">
            <button
              type="button"
              onClick={handleReset}
              disabled={isLoading}
              className="w-full sm:w-auto px-6 py-2 border border-gray-300 dark:border-gray-500 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500 disabled:opacity-50 transition"
            >
              Reset
            </button>
            <div className="flex items-center space-x-4">
                <button
                    type="button"
                    onClick={() => setCurrentStep(s => s - 1)}
                    disabled={currentStep === 0 || isLoading}
                    className="px-6 py-2 text-sm font-medium disabled:opacity-50"
                >
                    Back
                </button>
                {isLastStep ? (
                    <button
                        type="submit"
                        disabled={isGenerateDisabled}
                        className="w-full sm:w-auto flex items-center justify-center px-6 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-300 dark:disabled:bg-blue-800 disabled:cursor-not-allowed transition"
                    >
                        {isLoading ? 'Generating...' : 'Generate Files'}
                    </button>
                ) : (
                    <button
                        type="button"
                        onClick={() => setCurrentStep(s => s + 1)}
                        className="w-full sm:w-auto px-6 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700"
                    >
                        Next
                    </button>
                )}
            </div>
        </div>
    </form>
  );
};

export default AgentForm;

import React, { useState, useCallback, useEffect } from 'react';
import { AgentConfig, GeneratedFiles, SavedAgent } from '../types';
import { generateAgentFiles } from '../services/geminiService';
import * as db from '../services/dbService';
import AgentForm from './AgentForm';
import GeneratedFilesDisplay from './GeneratedFilesDisplay';
import LoadingSpinner from './LoadingSpinner';
import Modal from './Modal';
import Toast from './Toast';

const AgentArchitect: React.FC = () => {
  const [agentConfig, setAgentConfig] = useState<AgentConfig>({ role: '', scope: '', goals: '', constraints: '' });
  const [generatedFiles, setGeneratedFiles] = useState<GeneratedFiles | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const [savedAgents, setSavedAgents] = useState<SavedAgent[]>([]);
  const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingAgent, setEditingAgent] = useState<SavedAgent | null>(null);
  const [saveName, setSaveName] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  const loadSavedAgents = useCallback(async () => {
    const agents = await db.getAllAgents();
    setSavedAgents(agents);
  }, []);

  useEffect(() => {
    loadSavedAgents();
  }, [loadSavedAgents]);

  const handleGenerate = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setGeneratedFiles(null);
    try {
      if (!agentConfig.role || !agentConfig.scope) {
        setError("Agent Role and Scope are required fields.");
        return;
      }
      const files = await generateAgentFiles(agentConfig);
      setGeneratedFiles(files);
    } catch (e) {
      setError('Failed to generate agent files. Please check your API key and try again.');
    } finally {
      setIsLoading(false);
    }
  }, [agentConfig]);

  const handleReset = () => {
    setAgentConfig({ role: '', scope: '', goals: '', constraints: '' });
    setGeneratedFiles(null);
    setError(null);
    setIsLoading(false);
  };

  const handleOpenSaveModal = () => {
    setSaveName('');
    setError(null);
    setIsSaveModalOpen(true);
  };

  const handleSave = async () => {
    if (!saveName.trim() || !generatedFiles) {
      setError("Please provide a name.");
      return;
    }
    const newAgent: SavedAgent = {
      name: saveName.trim(),
      files: generatedFiles,
      createdAt: new Date().toISOString(),
    };
    await db.addAgent(newAgent);
    setSuccessMessage('Agent saved successfully!');
    setIsSaveModalOpen(false);
    setSaveName('');
    loadSavedAgents();
  };

  const handleOpenEditModal = (agent: SavedAgent) => {
    setEditingAgent(JSON.parse(JSON.stringify(agent))); // Deep copy
    setIsEditModalOpen(true);
  };

  const handleUpdate = async () => {
    if (!editingAgent) return;
    await db.updateAgent(editingAgent);
    setSuccessMessage('Agent updated successfully!');
    setIsEditModalOpen(false);
    setEditingAgent(null);
    loadSavedAgents();
  };

  const handleDelete = async (id: number) => {
    if (window.confirm('Are you sure you want to delete this agent?')) {
        await db.deleteAgent(id);
        loadSavedAgents();
    }
  };

  const handleLoadSavedAgent = (agent: SavedAgent) => {
      setGeneratedFiles(agent.files);
      window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  return (
    <div className="max-w-4xl mx-auto">
      <Toast message={successMessage} onClose={() => setSuccessMessage('')} />
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-6 md:p-8">
        <AgentForm 
          agentConfig={agentConfig} 
          setAgentConfig={setAgentConfig} 
          onGenerate={handleGenerate}
          onReset={handleReset}
          isLoading={isLoading} 
        />
      </div>

      {error && (
        <div className="mt-8 bg-red-100 dark:bg-red-900/50 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-200 px-4 py-3 rounded-lg relative" role="alert">
          <strong className="font-bold">Error: </strong>
          <span className="block sm:inline">{error}</span>
        </div>
      )}

      {isLoading && <LoadingSpinner />}

      {generatedFiles && !isLoading && (
        <div className="mt-8">
          <GeneratedFilesDisplay files={generatedFiles} onSave={handleOpenSaveModal} />
        </div>
      )}

      {savedAgents.length > 0 && (
        <div className="mt-12">
            <h2 className="text-2xl font-bold text-center mb-6">Saved Agents</h2>
            <div className="space-y-4">
                {savedAgents.map(agent => (
                    <div key={agent.id} className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-md flex justify-between items-center">
                        <div>
                            <p className="font-semibold">{agent.name}</p>
                            <p className="text-sm text-gray-500 dark:text-gray-400">Saved on {new Date(agent.createdAt).toLocaleDateString()}</p>
                        </div>
                        <div className="flex items-center space-x-2">
                            <button onClick={() => handleLoadSavedAgent(agent)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-blue-500 transition-colors" title="Load"><span className="material-icons">visibility</span></button>
                            <button onClick={() => handleOpenEditModal(agent)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-green-500 transition-colors" title="Edit"><span className="material-icons">edit</span></button>
                            <button onClick={() => handleDelete(agent.id!)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-red-500 transition-colors" title="Delete"><span className="material-icons">delete</span></button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
      )}

      <Modal isOpen={isSaveModalOpen} onClose={() => setIsSaveModalOpen(false)} title="Save Agent Configuration">
          <div className="space-y-4">
              <label htmlFor="saveName" className="block text-sm font-medium">Configuration Name</label>
              <input type="text" id="saveName" value={saveName} onChange={e => setSaveName(e.target.value)} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md" placeholder="e.g., My Financial Advisor Agent" />
              <div className="flex justify-end space-x-2 pt-2">
                  <button onClick={() => setIsSaveModalOpen(false)} className="px-4 py-2 rounded-md border dark:border-gray-600">Cancel</button>
                  <button onClick={handleSave} className="px-4 py-2 rounded-md bg-blue-600 text-white hover:bg-blue-700">Save</button>
              </div>
          </div>
      </Modal>

      <Modal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} title="Edit Agent Configuration">
          {editingAgent && <div className="space-y-4">
              <label htmlFor="editName" className="block text-sm font-medium">Name</label>
              <input type="text" id="editName" value={editingAgent.name} onChange={e => setEditingAgent({...editingAgent, name: e.target.value})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md" />
              <label className="block text-sm font-medium">Agent File</label>
              <textarea rows={5} value={editingAgent.files.agentFile} onChange={e => setEditingAgent({...editingAgent, files: {...editingAgent.files, agentFile: e.target.value}})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md font-mono text-sm" />
              <label className="block text-sm font-medium">Guidelines</label>
              <textarea rows={5} value={editingAgent.files.projectGuidelines} onChange={e => setEditingAgent({...editingAgent, files: {...editingAgent.files, projectGuidelines: e.target.value}})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md font-mono text-sm" />
              <label className="block text-sm font-medium">Constraints</label>
              <textarea rows={5} value={editingAgent.files.constraintsFile} onChange={e => setEditingAgent({...editingAgent, files: {...editingAgent.files, constraintsFile: e.target.value}})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md font-mono text-sm" />

              <div className="flex justify-end space-x-2 pt-2">
                  <button onClick={() => setIsEditModalOpen(false)} className="px-4 py-2 rounded-md border dark:border-gray-600">Cancel</button>
                  <button onClick={handleUpdate} className="px-4 py-2 rounded-md bg-blue-600 text-white hover:bg-blue-700">Update</button>
              </div>
          </div>}
      </Modal>

    </div>
  );
};

export default AgentArchitect;

import React, { useState, useCallback, useEffect } from 'react';
import { generateStructuredPrompt } from '../services/geminiService';
import { PromptConfig, SavedPrompt } from '../types';
import * as db from '../services/dbService';
import LoadingSpinner from './LoadingSpinner';
import Modal from './Modal';
import Toast from './Toast';

const PROMPT_TEMPLATES = [
    {
      name: 'Creative Content Generator',
      goal: 'Write a short, engaging blog post about a specified topic.',
      instructions: '1. Title: Create a catchy, SEO-friendly title.\n2. Introduction: Start with a hook to grab the reader\'s attention.\n3. Body: Write 3-4 paragraphs with clear headings.\n4. Conclusion: Summarize the key points and add a call-to-action.\n5. Tone: Friendly, informative, and slightly informal.'
    },
    {
      name: 'Technical Code Explainer',
      goal: 'Explain a given code snippet to a junior developer.',
      instructions: '1. High-Level Summary: Briefly explain what the code does.\n2. Line-by-Line Breakdown: Go through the code, explaining complex lines or functions.\n3. Concepts: Identify and explain the key programming concepts used.\n4. Simplification: Use an analogy or simple terms to clarify the logic.'
    },
    {
      name: 'Data Analysis Report',
      goal: 'Analyze a provided dataset (as text/csv) and summarize the key findings.',
      instructions: '1. Objective: State the main goal of the analysis.\n2. Key Insights: List the top 3-5 most important findings as bullet points.\n3. Observations: Mention any interesting patterns, trends, or outliers discovered.\n4. Recommendations: Suggest potential actions based on the analysis.\n5. Output Format: Present the report in clear, structured Markdown.'
    },
];

const PromptArchitect: React.FC = () => {
    const [promptConfig, setPromptConfig] = useState<PromptConfig>({ goal: '', instructions: '' });
    const [generatedPrompt, setGeneratedPrompt] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const [savedPrompts, setSavedPrompts] = useState<SavedPrompt[]>([]);
    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
    const [editingPrompt, setEditingPrompt] = useState<SavedPrompt | null>(null);
    const [saveName, setSaveName] = useState('');
    const [successMessage, setSuccessMessage] = useState('');

    const loadSavedPrompts = useCallback(async () => {
        const prompts = await db.getAllPrompts();
        setSavedPrompts(prompts);
    }, []);

    useEffect(() => {
        loadSavedPrompts();
    }, [loadSavedPrompts]);

    const handleGenerate = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        setGeneratedPrompt('');
        try {
            if (!promptConfig.goal.trim()) {
                setError("Please enter a goal for your prompt.");
                return;
            }
            const result = await generateStructuredPrompt(promptConfig);
            setGeneratedPrompt(result);
        } catch (e) {
            setError('Failed to generate prompt. Please check your API key and try again.');
        } finally {
            setIsLoading(false);
        }
    }, [promptConfig]);

    const handleReset = () => {
        setPromptConfig({ goal: '', instructions: '' });
        setGeneratedPrompt('');
        setError(null);
        setIsLoading(false);
    };

    const handleOpenSaveModal = () => {
        setSaveName('');
        setError(null);
        setIsSaveModalOpen(true);
    };

    const handleSave = async () => {
        if (!saveName.trim() || !generatedPrompt.trim()) {
            setError("Please provide a name.");
            return;
        }
        const newPrompt: SavedPrompt = {
            name: saveName.trim(),
            prompt: generatedPrompt,
            createdAt: new Date().toISOString(),
        };
        await db.addPrompt(newPrompt);
        setSuccessMessage('Prompt saved successfully!');
        setIsSaveModalOpen(false);
        setSaveName('');
        loadSavedPrompts();
    };

    const handleOpenEditModal = (prompt: SavedPrompt) => {
        setEditingPrompt(JSON.parse(JSON.stringify(prompt))); // Deep copy
        setIsEditModalOpen(true);
    };

    const handleUpdate = async () => {
        if (!editingPrompt) return;
        await db.updatePrompt(editingPrompt);
        setSuccessMessage('Prompt updated successfully!');
        setIsEditModalOpen(false);
        setEditingPrompt(null);
        loadSavedPrompts();
    };

    const handleDelete = async (id: number) => {
        if (window.confirm('Are you sure you want to delete this prompt?')) {
            await db.deletePrompt(id);
            loadSavedPrompts();
        }
    };

    const handleLoadSavedPrompt = (prompt: SavedPrompt) => {
        setGeneratedPrompt(prompt.prompt);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handleLoadTemplate = (template: { goal: string; instructions: string }) => {
        setPromptConfig({ goal: template.goal, instructions: template.instructions });
        setIsTemplateModalOpen(false);
    };

    return (
        <div className="max-w-4xl mx-auto">
            <Toast message={successMessage} onClose={() => setSuccessMessage('')} />
            <div className="mt-8 bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-6 md:p-8">
                <form onSubmit={(e) => { e.preventDefault(); handleGenerate(); }} className="space-y-6">
                    <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
                        <h2 className="text-2xl font-semibold text-gray-800 dark:text-gray-200">Define Your Prompt</h2>
                        <button type="button" onClick={() => setIsTemplateModalOpen(true)} className="w-full sm:w-auto flex items-center justify-center px-4 py-2 border border-blue-500 text-blue-500 dark:text-blue-400 dark:border-blue-400 rounded-md text-sm font-medium hover:bg-blue-50 dark:hover:bg-blue-900/40 transition">
                            <span className="material-icons mr-2 text-base">model_training</span>
                            Load Template
                        </button>
                    </div>
                    <div>
                        <label htmlFor="goal" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                            Prompt Goal / Core Task <span className="text-red-500">*</span>
                        </label>
                        <input type="text" id="goal" name="goal" value={promptConfig.goal} onChange={(e) => setPromptConfig(prev => ({...prev, goal: e.target.value}))} placeholder="e.g., 'Summarize technical articles for a beginner audience'" required className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition"/>
                    </div>
                    <div>
                        <label htmlFor="instructions" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                            Key Instructions, Constraints, or Steps (Optional)
                        </label>
                        <textarea id="instructions" name="instructions" rows={5} value={promptConfig.instructions} onChange={(e) => setPromptConfig(prev => ({...prev, instructions: e.target.value}))} placeholder="e.g., 'The summary must be in 3 bullet points. Avoid jargon. Mention the key takeaways for a marketer.'" className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition"/>
                    </div>
                    <div className="flex flex-col sm:flex-row items-center justify-end space-y-4 sm:space-y-0 sm:space-x-4 pt-2">
                        <button type="button" onClick={handleReset} disabled={isLoading} className="w-full sm:w-auto px-6 py-2 border border-gray-300 dark:border-gray-500 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500 disabled:opacity-50 transition">Reset</button>
                        <button type="submit" disabled={!promptConfig.goal.trim() || isLoading} className="w-full sm:w-auto flex items-center justify-center px-6 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-300 dark:disabled:bg-blue-800 disabled:cursor-not-allowed transition">
                            {isLoading ? 'Architecting...' : 'Generate Prompt'}
                        </button>
                    </div>
                </form>
            </div>

            {error && (
                <div className="mt-8 bg-red-100 dark:bg-red-900/50 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-200 px-4 py-3 rounded-lg" role="alert">
                    <strong className="font-bold">Error: </strong>
                    <span>{error}</span>
                </div>
            )}

            {isLoading && <LoadingSpinner />}

            {generatedPrompt && !isLoading && (
                <div className="mt-8 bg-white dark:bg-gray-800 rounded-2xl shadow-lg">
                     <div className="flex justify-between items-center p-4 border-b border-gray-200 dark:border-gray-700">
                        <h3 className="text-xl font-semibold">Generated Prompt</h3>
                        <div className="flex items-center space-x-2">
                           <button onClick={() => navigator.clipboard.writeText(generatedPrompt)} className="flex items-center px-3 py-1.5 border rounded-md text-sm" title="Copy prompt">
                                <span className="material-icons text-base mr-1.5">content_copy</span>Copy
                            </button>
                           <button onClick={handleOpenSaveModal} className="flex items-center px-3 py-1.5 border rounded-md text-sm bg-blue-500 text-white hover:bg-blue-600" title="Save prompt">
                                <span className="material-icons text-base mr-1.5">save</span>Save
                            </button>
                        </div>
                    </div>
                    <div className="prose prose-sm sm:prose-base dark:prose-dark max-w-none p-4 md:p-6 bg-gray-50 dark:bg-gray-900/70 rounded-b-lg whitespace-pre-wrap font-mono">
                        <pre><code className="text-sm">{generatedPrompt}</code></pre>
                    </div>
                </div>
            )}

            {savedPrompts.length > 0 && (
                <div className="mt-12">
                    <h2 className="text-2xl font-bold text-center mb-6">Saved Prompts</h2>
                    <div className="space-y-4">
                        {savedPrompts.map(p => (
                            <div key={p.id} className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-md flex justify-between items-center">
                                <div>
                                    <p className="font-semibold">{p.name}</p>
                                    <p className="text-sm text-gray-500 dark:text-gray-400">Saved on {new Date(p.createdAt).toLocaleDateString()}</p>
                                </div>
                                <div className="flex items-center space-x-2">
                                    <button onClick={() => handleLoadSavedPrompt(p)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-blue-500" title="Load"><span className="material-icons">visibility</span></button>
                                    <button onClick={() => handleOpenEditModal(p)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-green-500" title="Edit"><span className="material-icons">edit</span></button>
                                    <button onClick={() => handleDelete(p.id!)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-red-500" title="Delete"><span className="material-icons">delete</span></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <Modal isOpen={isTemplateModalOpen} onClose={() => setIsTemplateModalOpen(false)} title="Load a Prompt Template">
                <div className="space-y-3 max-h-[60vh] overflow-y-auto">
                    {PROMPT_TEMPLATES.map((template) => (
                        <button 
                            key={template.name} 
                            onClick={() => handleLoadTemplate(template)}
                            className="w-full text-left p-4 rounded-lg bg-gray-50 dark:bg-gray-700 hover:bg-blue-100 dark:hover:bg-blue-900/50 border dark:border-gray-600 transition"
                        >
                            <h4 className="font-semibold text-gray-800 dark:text-gray-200">{template.name}</h4>
                            <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">{template.goal}</p>
                        </button>
                    ))}
                </div>
            </Modal>

            <Modal isOpen={isSaveModalOpen} onClose={() => setIsSaveModalOpen(false)} title="Save Prompt">
                <div className="space-y-4">
                    <label htmlFor="saveName" className="block text-sm font-medium">Prompt Name</label>
                    <input type="text" id="saveName" value={saveName} onChange={e => setSaveName(e.target.value)} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md" placeholder="e.g., My Technical Summarizer" />
                    <div className="flex justify-end space-x-2 pt-2">
                        <button onClick={() => setIsSaveModalOpen(false)} className="px-4 py-2 rounded-md border dark:border-gray-600">Cancel</button>
                        <button onClick={handleSave} className="px-4 py-2 rounded-md bg-blue-600 text-white">Save</button>
                    </div>
                </div>
            </Modal>

            <Modal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} title="Edit Prompt">
                {editingPrompt && <div className="space-y-4">
                    <label htmlFor="editName" className="block text-sm font-medium">Name</label>
                    <input type="text" id="editName" value={editingPrompt.name} onChange={e => setEditingPrompt({...editingPrompt, name: e.target.value})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md" />
                    <label className="block text-sm font-medium">Prompt</label>
                    <textarea rows={10} value={editingPrompt.prompt} onChange={e => setEditingPrompt({...editingPrompt, prompt: e.target.value})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md font-mono text-sm" />
                    <div className="flex justify-end space-x-2 pt-2">
                        <button onClick={() => setIsEditModalOpen(false)} className="px-4 py-2 rounded-md border dark:border-gray-600">Cancel</button>
                        <button onClick={handleUpdate} className="px-4 py-2 rounded-md bg-blue-600 text-white">Update</button>
                    </div>
                </div>}
            </Modal>
        </div>
    );
};

export default PromptArchitect;

export interface AgentConfig {
  role: string;
  scope: string;
  goals: string;
  constraints: string;
}

export interface GeneratedFiles {
  agentFile: string;
  projectGuidelines: string;
  constraintsFile: string;
}

export interface PromptConfig {
  goal: string;
  instructions: string;
}

export interface SavedAgent {
  id?: number;
  name: string;
  config: AgentConfig;
  files: GeneratedFiles;
  createdAt: string; // ISO string for easier storage
}

export interface SavedPrompt {
  id?: number;
  name: string;
  config: PromptConfig;
  prompt: string;
  createdAt: string; // ISO string
}

import React, { useState, useCallback, useEffect } from 'react';
import { AgentConfig, GeneratedFiles, SavedAgent } from '../types';
import { generateAgentFiles } from '../services/geminiService';
import * as db from '../services/dbService';
import AgentForm from './AgentForm';
import GeneratedFilesDisplay from './GeneratedFilesDisplay';
import LoadingSpinner from './LoadingSpinner';
import Modal from './Modal';
import Toast from './Toast';

const AgentArchitect: React.FC = () => {
  const [agentConfig, setAgentConfig] = useState<AgentConfig>({ role: '', scope: '', goals: '', constraints: '' });
  const [generatedFiles, setGeneratedFiles] = useState<GeneratedFiles | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const [savedAgents, setSavedAgents] = useState<SavedAgent[]>([]);
  const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingAgent, setEditingAgent] = useState<SavedAgent | null>(null);
  const [saveName, setSaveName] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  const loadSavedAgents = useCallback(async () => {
    const agents = await db.getAllAgents();
    setSavedAgents(agents);
  }, []);

  useEffect(() => {
    loadSavedAgents();
  }, [loadSavedAgents]);

  const handleGenerate = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setGeneratedFiles(null);
    try {
      if (!agentConfig.role || !agentConfig.scope) {
        setError("Agent Role and Scope are required fields.");
        return;
      }
      const files = await generateAgentFiles(agentConfig);
      setGeneratedFiles(files);
    } catch (e) {
      setError('Failed to generate agent files. Please check your API key and try again.');
    } finally {
      setIsLoading(false);
    }
  }, [agentConfig]);

  const handleReset = () => {
    setAgentConfig({ role: '', scope: '', goals: '', constraints: '' });
    setGeneratedFiles(null);
    setError(null);
    setIsLoading(false);
  };

  const handleOpenSaveModal = () => {
    setSaveName('');
    setError(null);
    setIsSaveModalOpen(true);
  };

  const handleSave = async () => {
    if (!saveName.trim() || !generatedFiles) {
      setError("Please provide a name.");
      return;
    }
    const newAgent: SavedAgent = {
      name: saveName.trim(),
      config: agentConfig,
      files: generatedFiles,
      createdAt: new Date().toISOString(),
    };
    await db.addAgent(newAgent);
    setSuccessMessage('Agent saved successfully!');
    setIsSaveModalOpen(false);
    setSaveName('');
    loadSavedAgents();
  };

  const handleOpenEditModal = (agent: SavedAgent) => {
    setEditingAgent(JSON.parse(JSON.stringify(agent))); // Deep copy
    setIsEditModalOpen(true);
  };

  const handleUpdate = async () => {
    if (!editingAgent) return;
    await db.updateAgent(editingAgent);
    setSuccessMessage('Agent updated successfully!');
    setIsEditModalOpen(false);
    setEditingAgent(null);
    loadSavedAgents();
  };

  const handleDelete = async (id: number) => {
    if (window.confirm('Are you sure you want to delete this agent?')) {
        await db.deleteAgent(id);
        loadSavedAgents();
    }
  };

  const handleLoadSavedAgent = (agent: SavedAgent) => {
      setAgentConfig(agent.config);
      setGeneratedFiles(agent.files);
      window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  return (
    <div className="max-w-4xl mx-auto">
      <Toast message={successMessage} onClose={() => setSuccessMessage('')} />
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-6 md:p-8">
        <AgentForm 
          agentConfig={agentConfig} 
          setAgentConfig={setAgentConfig} 
          onGenerate={handleGenerate}
          onReset={handleReset}
          isLoading={isLoading} 
        />
      </div>

      {error && (
        <div className="mt-8 bg-red-100 dark:bg-red-900/50 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-200 px-4 py-3 rounded-lg relative" role="alert">
          <strong className="font-bold">Error: </strong>
          <span className="block sm:inline">{error}</span>
        </div>
      )}

      {isLoading && <LoadingSpinner />}

      {generatedFiles && !isLoading && (
        <div className="mt-8">
          <GeneratedFilesDisplay files={generatedFiles} onSave={handleOpenSaveModal} />
        </div>
      )}

      {savedAgents.length > 0 && (
        <div className="mt-12">
            <h2 className="text-2xl font-bold text-center mb-6">Saved Agents</h2>
            <div className="space-y-4">
                {savedAgents.map(agent => (
                    <div key={agent.id} className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-md flex justify-between items-center">
                        <div>
                            <p className="font-semibold">{agent.name}</p>
                            <p className="text-sm text-gray-500 dark:text-gray-400">Saved on {new Date(agent.createdAt).toLocaleDateString()}</p>
                        </div>
                        <div className="flex items-center space-x-2">
                            <button onClick={() => handleLoadSavedAgent(agent)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-blue-500 transition-colors" title="Load"><span className="material-icons">visibility</span></button>
                            <button onClick={() => handleOpenEditModal(agent)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-green-500 transition-colors" title="Edit"><span className="material-icons">edit</span></button>
                            <button onClick={() => handleDelete(agent.id!)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-red-500 transition-colors" title="Delete"><span className="material-icons">delete</span></button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
      )}

      <Modal isOpen={isSaveModalOpen} onClose={() => setIsSaveModalOpen(false)} title="Save Agent Configuration">
          <div className="space-y-4">
              <label htmlFor="saveName" className="block text-sm font-medium">Configuration Name</label>
              <input type="text" id="saveName" value={saveName} onChange={e => setSaveName(e.target.value)} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md" placeholder="e.g., My Financial Advisor Agent" />
              <div className="flex justify-end space-x-2 pt-2">
                  <button onClick={() => setIsSaveModalOpen(false)} className="px-4 py-2 rounded-md border dark:border-gray-600">Cancel</button>
                  <button onClick={handleSave} className="px-4 py-2 rounded-md bg-blue-600 text-white hover:bg-blue-700">Save</button>
              </div>
          </div>
      </Modal>

      <Modal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} title="Edit Agent Configuration">
          {editingAgent && <div className="space-y-4">
              <label htmlFor="editName" className="block text-sm font-medium">Name</label>
              <input type="text" id="editName" value={editingAgent.name} onChange={e => setEditingAgent({...editingAgent, name: e.target.value})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md" />
              <label className="block text-sm font-medium">Agent File</label>
              <textarea rows={5} value={editingAgent.files.agentFile} onChange={e => setEditingAgent({...editingAgent, files: {...editingAgent.files, agentFile: e.target.value}})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md font-mono text-sm" />
              <label className="block text-sm font-medium">Guidelines</label>
              <textarea rows={5} value={editingAgent.files.projectGuidelines} onChange={e => setEditingAgent({...editingAgent, files: {...editingAgent.files, projectGuidelines: e.target.value}})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md font-mono text-sm" />
              <label className="block text-sm font-medium">Constraints</label>
              <textarea rows={5} value={editingAgent.files.constraintsFile} onChange={e => setEditingAgent({...editingAgent, files: {...editingAgent.files, constraintsFile: e.target.value}})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border rounded-md font-mono text-sm" />

              <div className="flex justify-end space-x-2 pt-2">
                  <button onClick={() => setIsEditModalOpen(false)} className="px-4 py-2 rounded-md border dark:border-gray-600">Cancel</button>
                  <button onClick={handleUpdate} className="px-4 py-2 rounded-md bg-blue-600 text-white hover:bg-blue-700">Update</button>
              </div>
          </div>}
      </Modal>

    </div>
  );
};

export default AgentArchitect;

