import React, { useState, useCallback, useEffect, useRef } from 'react';
import { ProjectConfig, GeneratedProjectFiles, SavedProject } from '../types';
import { generateProjectFiles } from '../services/geminiService';
import * as db from '../services/dbService';
import ProjectForm from './ProjectForm';
import GeneratedProjectDisplay from './GeneratedProjectDisplay';
import LoadingSpinner from './LoadingSpinner';
import Modal from './Modal';
import Toast from './Toast';

const ProjectArchitect: React.FC = () => {
  const [projectConfig, setProjectConfig] = useState<ProjectConfig>({
    title: '', idea: '', vision: '', goal: '', rules: '',
    constraints: '', guidelines: '', roles: '', standards: '', consistency: ''
  });
  const [generatedFiles, setGeneratedFiles] = useState<GeneratedProjectFiles | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [loadedProjectName, setLoadedProjectName] = useState<string | undefined>(undefined);
  const [loadingMessage, setLoadingMessage] = useState('');
  const loadingIntervalRef = useRef<number | null>(null);

  const [savedProjects, setSavedProjects] = useState<SavedProject[]>([]);
  const [successMessage, setSuccessMessage] = useState('');
  const [draftStatus, setDraftStatus] = useState<'unloaded' | 'loaded' | 'none'>('unloaded');

  const [modalState, setModalState] = useState<{ mode: 'save' | 'edit'; project?: SavedProject } | null>(null);
  const [modalInput, setModalInput] = useState<{ name: string; files: GeneratedProjectFiles | null }>({ name: '', files: null });

  const loadSavedProjects = useCallback(async () => {
    const projects = await db.getAllProjects();
    setSavedProjects(projects);
  }, []);

  useEffect(() => {
    loadSavedProjects();
    const loadDraft = async () => {
      const draft = await db.getProjectDraft(1);
      if (draft?.config && Object.values(draft.config).some(v => v)) {
        if (window.confirm("An unsaved project draft was found. Do you want to load it?")) {
          setProjectConfig(draft.config);
          setDraftStatus('loaded');
        } else {
          await db.clearProjectDraft(1);
          setDraftStatus('none');
        }
      } else {
        setDraftStatus('none');
      }
    };
    loadDraft();
  }, [loadSavedProjects]);

  useEffect(() => {
    if (draftStatus === 'unloaded') return;
    const handler = setTimeout(() => {
      if (Object.values(projectConfig).some(value => typeof value === 'string' && value.length > 0)) {
        db.saveProjectDraft({ id: 1, config: projectConfig });
      }
    }, 1500);
    return () => clearTimeout(handler);
  }, [projectConfig, draftStatus]);

  const handleGenerate = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setGeneratedFiles(null);

    const messages = ['Architecting project vision...', 'Defining standards & roles...', 'Establishing rules & guardrails...'];
    let messageIndex = 0;
    setLoadingMessage(messages[0]);
    loadingIntervalRef.current = window.setInterval(() => {
      messageIndex = (messageIndex + 1) % messages.length;
      setLoadingMessage(messages[messageIndex]);
    }, 2000);

    try {
      if (!projectConfig.title || !projectConfig.goal) {
        setError("Project Title and Goal are required fields.");
        return;
      }
      const files = await generateProjectFiles(projectConfig);
      setGeneratedFiles(files);
      await db.clearProjectDraft(1);
    } catch (e) {
      setError('Failed to generate project files. Please check your API key and try again.');
    } finally {
      setIsLoading(false);
      if(loadingIntervalRef.current) {
        clearInterval(loadingIntervalRef.current);
      }
      setLoadingMessage('');
    }
  }, [projectConfig]);

  const handleReset = () => {
    setProjectConfig({
      title: '', idea: '', vision: '', goal: '', rules: '',
      constraints: '', guidelines: '', roles: '', standards: '', consistency: ''
    });
    setGeneratedFiles(null);
    setError(null);
    setIsLoading(false);
    setLoadedProjectName(undefined);
    db.clearProjectDraft(1);
  };

  const handleOpenSaveModal = () => {
    if (!generatedFiles) return;
    setModalInput({ name: loadedProjectName || '', files: generatedFiles });
    setModalState({ mode: 'save' });
  };

  const handleOpenEditModal = (project: SavedProject) => {
    setModalInput({ name: project.name, files: project.files });
    setModalState({ mode: 'edit', project });
  };

  const handleModalSave = async () => {
    if (!modalState || !modalInput.name.trim() || !modalInput.files) return;

    if (modalState.mode === 'save') {
      const newProject: SavedProject = {
        name: modalInput.name.trim(),
        config: projectConfig,
        files: modalInput.files,
        createdAt: new Date().toISOString(),
      };
      await db.addProject(newProject);
      setSuccessMessage('Project saved successfully!');
    } else if (modalState.mode === 'edit' && modalState.project) {
      const updatedProject: SavedProject = {
        ...modalState.project,
        name: modalInput.name.trim(),
        files: modalInput.files,
      };
      await db.updateProject(updatedProject);
      setSuccessMessage('Project updated successfully!');
    }

    loadSavedProjects();
    setModalState(null);
  };

  const handleDelete = async (id: number) => {
    if (window.confirm('Are you sure you want to delete this project?')) {
      try {
        await db.deleteProject(id);
        setSavedProjects(prev => prev.filter(p => p.id !== id));
        setSuccessMessage('Project deleted successfully!');
      } catch (err) {
        setError('Failed to delete project.');
      }
    }
  };

  const handleClearAll = async () => {
    if (window.confirm('Are you sure you want to delete ALL saved projects? This action cannot be undone.')) {
      try {
        await db.clearAllProjects();
        setSavedProjects([]);
        setSuccessMessage('All projects have been deleted.');
      } catch (err) {
        setError('Failed to clear all projects.');
      }
    }
  };

  const handleLoadSavedProject = (project: SavedProject) => {
    setProjectConfig(project.config);
    setGeneratedFiles(project.files);
    setLoadedProjectName(project.name);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className="max-w-4xl mx-auto">
      <Toast message={successMessage} onClose={() => setSuccessMessage('')} />
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-6 md:p-8">
        <ProjectForm 
          projectConfig={projectConfig} 
          setProjectConfig={setProjectConfig} 
          onGenerate={handleGenerate}
          onReset={handleReset}
          isLoading={isLoading} 
        />
      </div>

      {error && (
        <div className="mt-8 bg-red-100 dark:bg-red-900/50 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-200 px-4 py-3 rounded-lg relative" role="alert">
          <strong className="font-bold">Error: </strong>
          <span className="block sm:inline">{error}</span>
        </div>
      )}

      {isLoading && <LoadingSpinner message={loadingMessage} />}

      {generatedFiles && !isLoading && (
        <div className="mt-8">
          <GeneratedProjectDisplay files={generatedFiles} onSave={handleOpenSaveModal} projectName={loadedProjectName} />
        </div>
      )}

      {savedProjects.length > 0 && (
        <div className="mt-12">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-center">Saved Projects</h2>
                <button onClick={handleClearAll} className="px-4 py-2 text-sm font-medium text-red-600 dark:text-red-400 bg-red-100 dark:bg-red-900/30 rounded-lg hover:bg-red-200 dark:hover:bg-red-900/60">
                    Clear All
                </button>
            </div>
            <div className="space-y-4">
                {savedProjects.map(project => (
                    <div key={project.id} className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-md flex justify-between items-center">
                        <div>
                            <p className="font-semibold">{project.name}</p>
                            <p className="text-sm text-gray-500 dark:text-gray-400">Saved on {new Date(project.createdAt).toLocaleDateString()}</p>
                        </div>
                        <div className="flex items-center space-x-2">
                            <button onClick={() => handleLoadSavedProject(project)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-blue-500 transition-colors" title="Load"><span className="material-icons">visibility</span></button>
                            <button onClick={() => handleOpenEditModal(project)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-green-500 transition-colors" title="Edit"><span className="material-icons">edit</span></button>
                            <button onClick={() => handleDelete(project.id!)} className="p-2 text-gray-600 dark:text-gray-300 hover:text-red-500 transition-colors" title="Delete"><span className="material-icons">delete</span></button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
      )}

      <Modal isOpen={!!modalState} onClose={() => setModalState(null)} title={modalState?.mode === 'edit' ? 'Edit Project' : 'Save Project Blueprint'}>
          {modalState && <div className="space-y-4">
              <label htmlFor="modalProjectName" className="block text-sm font-medium">Name</label>
              <input type="text" id="modalProjectName" value={modalInput.name} onChange={e => setModalInput({...modalInput, name: e.target.value})} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" placeholder="e.g., Q3 Marketing Campaign AI Suite" />

              {modalState.mode === 'edit' && modalInput.files && (
                  <div className="max-h-64 overflow-y-auto space-y-4 pr-2">
                    <label className="block text-sm font-medium pt-2">Project Overview</label>
                    <textarea rows={5} value={modalInput.files.overviewFile} onChange={e => setModalInput(prev => ({...prev, files: {...prev.files!, overviewFile: e.target.value}}))} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md font-mono text-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
                    <label className="block text-sm font-medium">Development Standards</label>
                    <textarea rows={5} value={modalInput.files.standardsFile} onChange={e => setModalInput(prev => ({...prev, files: {...prev.files!, standardsFile: e.target.value}}))} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md font-mono text-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
                    <label className="block text-sm font-medium">Rules & Guardrails</label>
                    <textarea rows={5} value={modalInput.files.rulesFile} onChange={e => setModalInput(prev => ({...prev, files: {...prev.files!, rulesFile: e.target.value}}))} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md font-mono text-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
                  </div>
              )}

              <div className="flex justify-end space-x-2 pt-2">
                  <button onClick={() => setModalState(null)} className="px-4 py-2 rounded-md border dark:border-gray-600">Cancel</button>
                  <button onClick={handleModalSave} className="px-4 py-2 rounded-md bg-blue-600 text-white hover:bg-blue-700">{modalState.mode === 'edit' ? 'Update' : 'Save'}</button>
              </div>
          </div>}
      </Modal>

    </div>
  );
};

export default ProjectArchitect;

import React from 'react';
import { ProjectConfig } from '../types';

interface ProjectFormProps {
  projectConfig: ProjectConfig;
  setProjectConfig: React.Dispatch<React.SetStateAction<ProjectConfig>>;
  onGenerate: () => void;
  onReset: () => void;
  isLoading: boolean;
}

const Tooltip: React.FC<{ text: string }> = ({ text }) => (
  <span className="absolute left-1/2 -translate-x-1/2 bottom-full mb-2 w-max max-w-xs p-2 bg-gray-800 text-white text-xs rounded-md shadow-lg opacity-0 group-hover:opacity-100 transition-opacity z-10 pointer-events-none">
    {text}
  </span>
);

const FormField: React.FC<{id: string, label: string, tooltip: string, required: boolean, children: React.ReactNode}> = ({id, label, tooltip, required, children}) => (
    <div className="mb-4">
        <label htmlFor={id} className="flex items-center text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            {label} {required ? <span className="text-red-500 ml-1">*</span> : '(Optional)'}
            <div className="group relative flex items-center ml-2">
                <span className="material-icons text-gray-400 dark:text-gray-500 text-base cursor-help">info_outline</span>
                <Tooltip text={tooltip} />
            </div>
        </label>
        {children}
    </div>
);

const Fieldset: React.FC<{legend: string, children: React.ReactNode}> = ({legend, children}) => (
    <fieldset className="border border-gray-300 dark:border-gray-600 rounded-lg p-4 pt-2">
        <legend className="text-lg font-semibold px-2 text-gray-800 dark:text-gray-200">{legend}</legend>
        {children}
    </fieldset>
);


const ProjectForm: React.FC<ProjectFormProps> = ({ projectConfig, setProjectConfig, onGenerate, onReset, isLoading }) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setProjectConfig(prev => ({ ...prev, [name]: value }));
  };

  const isGenerateDisabled = !projectConfig.title || !projectConfig.goal || isLoading;

  return (
    <form onSubmit={(e) => { e.preventDefault(); onGenerate(); }} className="space-y-8">
        <h2 className="text-3xl font-bold text-center text-gray-800 dark:text-gray-200">Architect a New Project</h2>

        <Fieldset legend="Core Concepts">
            <FormField id="title" label="Name / Title" tooltip="A clear, concise name for your project." required>
                 <input
                    type="text"
                    id="title"
                    name="title"
                    value={projectConfig.title}
                    onChange={handleChange}
                    placeholder="e.g., Automated Content Generation Pipeline"
                    required
                    className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20"
                />
            </FormField>
             <FormField id="goal" label="Project Goal" tooltip="The primary, measurable objective of this project." required>
                 <input
                    type="text"
                    id="goal"
                    name="goal"
                    value={projectConfig.goal}
                    onChange={handleChange}
                    placeholder="e.g., To increase blog post output by 300% within Q3"
                    required
                    className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20"
                />
            </FormField>
            <FormField id="idea" label="Project Idea" tooltip="A high-level summary of the project concept.">
                <textarea rows={2} id="idea" name="idea" value={projectConfig.idea} onChange={handleChange} placeholder="Describe the core idea in a sentence or two." className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
            </FormField>
            <FormField id="vision" label="Project Vision" tooltip="The long-term aspiration or impact of the project.">
                <textarea rows={2} id="vision" name="vision" value={projectConfig.vision} onChange={handleChange} placeholder="What is the ultimate future state this project enables?" className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
            </FormField>
        </Fieldset>

        <Fieldset legend="Operational Rules">
            <FormField id="rules" label="Project Rules" tooltip="Core principles or commandments that must be followed.">
                <textarea rows={3} id="rules" name="rules" value={projectConfig.rules} onChange={handleChange} placeholder="e.g., 1. All code must be reviewed. 2. User privacy is paramount." className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
            </FormField>
            <FormField id="constraints" label="Project Constraints" tooltip="Specific limitations (e.g., budget, technology, timeline).">
                <textarea rows={3} id="constraints" name="constraints" value={projectConfig.constraints} onChange={handleChange} placeholder="e.g., Must use the existing Python backend. Cannot access external APIs without approval." className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
            </FormField>
            <FormField id="guidelines" label="Guidelines & Guardrails" tooltip="Best practices and safety measures to keep the project on track.">
                <textarea rows={3} id="guidelines" name="guidelines" value={projectConfig.guidelines} onChange={handleChange} placeholder="e.g., AI-generated content should be clearly marked. Avoid generating content on sensitive topics." className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
            </FormField>
        </Fieldset>

        <Fieldset legend="Team & Standards">
             <FormField id="roles" label="Project Developer Roles" tooltip="Define the key roles and their primary responsibilities.">
                <textarea rows={3} id="roles" name="roles" value={projectConfig.roles} onChange={handleChange} placeholder="e.g., Lead AI Engineer: Manages model integration. Frontend Dev: Builds UI components." className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
            </FormField>
             <FormField id="standards" label="Project Standards" tooltip="Technical standards for code, documentation, and testing.">
                <textarea rows={3} id="standards" name="standards" value={projectConfig.standards} onChange={handleChange} placeholder="e.g., All functions must have docstrings. Unit test coverage must be > 80%." className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
            </FormField>
             <FormField id="consistency" label="Project Consistency" tooltip="Rules for maintaining consistency in UI, API design, etc.">
                <textarea rows={3} id="consistency" name="consistency" value={projectConfig.consistency} onChange={handleChange} placeholder="e.g., All API endpoints must be versioned. UI components must adhere to the design system." className="w-full px-4 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm transition focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:ring-2 hover:ring-blue-500/20" />
            </FormField>
        </Fieldset>

        <div className="flex flex-col sm:flex-row items-center justify-end space-y-4 sm:space-y-0 sm:space-x-4 pt-4">
            <button
              type="button"
              onClick={onReset}
              disabled={isLoading}
              className="w-full sm:w-auto px-6 py-2 border border-gray-300 dark:border-gray-500 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500 disabled:opacity-50 transition"
            >
              Reset
            </button>
            <button
                type="submit"
                disabled={isGenerateDisabled}
                className="w-full sm:w-auto flex items-center justify-center px-6 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-300 dark:disabled:bg-blue-800 disabled:cursor-not-allowed transition"
            >
                {isLoading ? 'Generating...' : 'Generate Blueprint'}
            </button>
        </div>
    </form>
  );
};

export default ProjectForm;

import React, { useState } from 'react';
import { GeneratedProjectFiles } from '../types';

interface GeneratedProjectDisplayProps {
  files: GeneratedProjectFiles;
  onSave: () => void;
  projectName?: string;
}

type Tab = 'overviewFile' | 'standardsFile' | 'rulesFile';

const FileContent: React.FC<{ content: string }> = ({ content }) => (
    <div className="prose prose-sm sm:prose-base dark:prose-dark max-w-none p-4 md:p-6 bg-gray-50 dark:bg-gray-900/70 rounded-b-lg whitespace-pre-wrap font-mono">
        <pre><code className="text-sm">{content}</code></pre>
    </div>
);


const GeneratedProjectDisplay: React.FC<GeneratedProjectDisplayProps> = ({ files, onSave, projectName }) => {
  const [activeTab, setActiveTab] = useState<Tab>('overviewFile');
  const [copyAllText, setCopyAllText] = useState('Copy All');

  const tabs: { id: Tab; label: string; icon: string }[] = [
    { id: 'overviewFile', label: 'Overview', icon: 'visibility' },
    { id: 'standardsFile', label: 'Standards', icon: 'integration_instructions' },
    { id: 'rulesFile', label: 'Rules', icon: 'gavel' },
  ];

  const handleCopyAll = () => {
    const allContent = `
--- FILE: project-overview.md ---

${files.overviewFile}

--- FILE: development-standards.md ---

${files.standardsFile}

--- FILE: rules-and-guardrails.md ---

${files.rulesFile}
    `.trim();
    navigator.clipboard.writeText(allContent);
    setCopyAllText('Copied!');
    setTimeout(() => setCopyAllText('Copy All'), 2000);
  };

  const handleExportAll = () => {
    const prefix = projectName ? projectName.replace(/\s+/g, '-').toLowerCase() : 'project-export';
    const filesToExport = {
        [`${prefix}-overview.md`]: files.overviewFile,
        [`${prefix}-standards.md`]: files.standardsFile,
        [`${prefix}-rules.md`]: files.rulesFile,
    };

    for (const [filename, content] of Object.entries(filesToExport)) {
        const blob = new Blob([content], { type: 'text/markdown;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    }
  };

  return (
    <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg mt-10">
        <div className="flex flex-wrap justify-between items-center p-4 border-b border-gray-200 dark:border-gray-700 gap-4">
            <h3 className="text-xl font-semibold">Generated Project Blueprint</h3>
            <div className="flex items-center space-x-2">
                <button onClick={handleCopyAll} className="flex items-center px-3 py-1.5 border rounded-md text-sm" title="Copy all files">
                    <span className="material-icons text-base mr-1.5">collections</span>{copyAllText}
                </button>
                <button onClick={handleExportAll} className="flex items-center px-3 py-1.5 border rounded-md text-sm" title="Export all files">
                    <span className="material-icons text-base mr-1.5">download</span>Export All
                </button>
                 <button 
                    onClick={onSave} 
                    className="flex items-center px-3 py-1.5 border border-transparent rounded-md text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 transition" 
                    title="Save project blueprint"
                >
                    <span className="material-icons text-base mr-1.5">save</span>
                    Save
                </button>
            </div>
        </div>
      <div className="border-b border-gray-200 dark:border-gray-700">
        <nav className="-mb-px flex space-x-1 sm:space-x-4 px-4" aria-label="Tabs">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`
                ${activeTab === tab.id
                  ? 'border-blue-500 text-blue-600 dark:border-blue-400 dark:text-blue-300'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300 dark:text-gray-400 dark:hover:text-gray-200 dark:hover:border-gray-600'
                }
                flex items-center whitespace-nowrap py-4 px-1 sm:px-2 border-b-2 font-medium text-sm transition-colors focus:outline-none
              `}
            >
              <span className="material-icons text-base mr-2">{tab.icon}</span>
              {tab.label}
            </button>
          ))}
        </nav>
      </div>
      <div>
        <FileContent content={files[activeTab]} />
      </div>
    </div>
  );
};

export default GeneratedProjectDisplay;
